INSERT INTO public.site_meta (key, value) VALUES ('bmAudit', $m25j${"missingScanNote":"Page livret 184/273 absente du scan PDF (Ch. 29 Q20–Q25 + énoncé Q26) : 100 % RÉCUPÉRÉE avec certitude via la bijection exacte Ch. 29 Q(k+8) == Ch. 41 Q(k) (Ch. 41 Q12–Q18).","outOfCourseVisible":114,"matchedChapterComplements":52,"distinctCoursesCount":25,"matchedTo25Courses":362,"matchedDirectInSlides":310,"matchedTo12Courses":362,"recoveredScanQuestions":6,"pagesScanned":188,"coverClaimedCount":772,"unansweredSolvedCount":114,"chaptersCount":43,"missingScanQuestions":0,"courseFilesCount":51,"actualVerifiedCount":476,"bmCorrigeErrorsCount":26,"documentName":"BM Épidémiologie 2026 (Banque MAGIC QCM — Batna 2, 2012–2025)"}$m25j$::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
INSERT INTO public.site_meta (key, value) VALUES ('bmErrors', $m25j$[{"courseId":"C1","bmAnswer":"C","id":"ERR_1","courseAnswer":"B","bmRef":"Ch. 2 Q1 (2024)","lessonId":"L1.1","topic":"Approche prospective de la santé","reason":"L’item C (dimensions physique, mentale, sociale) définit l’approche globaliste (OMS 1946). L’approche prospective (B) tient compte des moyens de contrôle des facteurs endogènes et exogènes.","courseProof":"Intro SP — Pr Boumaraf, slides 7 \u0026 9"},{"courseId":"C1","bmAnswer":"ABC","id":"ERR_2","courseAnswer":"C uniquement","bmRef":"Ch. 14 Q2 (2025)","lessonId":"L1.1","topic":"Approche conventionnelle de la santé","reason":"L’approche conventionnelle se définit « en dehors de tout critère socio-économique et culturel ». A et B sont formellement faux.","courseProof":"Intro SP — Pr Boumaraf, slides 5–6"},{"courseId":"C18","bmAnswer":"B","id":"ERR_3","courseAnswer":"BC","bmRef":"Ch. 5 Q3 (2024)","lessonId":"L18.1","topic":"Épidémiologie des méningites à méningocoque","reason":"Transmission aérienne par gouttelettes (B) ET colonisation du rhinopharynx chez ~25 % des porteurs sains (C) sont toutes deux verbatim exactes dans le cours.","courseProof":"Présentation M MS.ppt — Dr K. Toureche, [28] \u0026 [30]"},{"courseId":"C23","bmAnswer":"C.","id":"ERR_4","courseAnswer":"A","bmRef":"Ch. 7 Q1 (2024)","lessonId":"L23.1","topic":"Communication orale : règle OUAC","reason":"L’orateur doit choisir un Objectif Unique et Absolu de Communication (OUAC = A). Confirmé par son doublon exact Ch. 7 Q2 = A !","courseProof":"Communication scientifique 2023 — Kadir MY, slides 15–16"},{"courseId":"C23","bmAnswer":"D","id":"ERR_5","courseAnswer":"B","bmRef":"Ch. 7 Q4 (2024) == Ch. 14 Q7","lessonId":"L23.1","topic":"Les 3 objectifs de la communication scientifique","reason":"Les 3 objectifs scientifiques sont mot pour mot : Accessibilité, Compréhensibilité et Crédibilité (B). L’item D confond avec le ciblage des publics.","courseProof":"Communication scientifique 2023 — Kadir MY, slides 22–23"},{"courseId":"C6","bmAnswer":"ABC","id":"ERR_6","courseAnswer":"AD","bmRef":"Ch. 10 Q6 (2022)","lessonId":"L6.3","topic":"Règles d’hygiène des mains","reason":"Le pain de savon (B) et la serviette tissu réutilisable (C) sont proscrits (réservoirs). Seuls savon liquide doux (A) et essuie-main papier / proscription sèche-mains électrique (D) sont conformes.","courseProof":"Hygiène-des-mains.pptx, Notes 11 \u0026 17 + Ch. 10 Q20"},{"courseId":"C6","bmAnswer":"C","id":"ERR_7","courseAnswer":"A","bmRef":"Ch. 10 Q14 (2021)","lessonId":"L6.1","topic":"Délai ISO sur prothèse du genou (2 mois)","reason":"Le délai ISO est de 30 jours en chirurgie sans matériel, mais passe à 1 AN en cas d’implant ou de prothèse : à 2 mois, c’est bien une ISO (A).","courseProof":"Les infections associées aux soins.pptx — slide 6"},{"courseId":"C6","bmAnswer":"A (1-4)","id":"ERR_8","courseAnswer":"D (1-2-4)","bmRef":"Ch. 10 Q21 (ND)","lessonId":"L6.1","topic":"Définition IAS (IN + ILS)","reason":"Les IAS englobent les IN (hôpital) ET les infections liées aux soins en milieu libéral (ILS, item 2).","courseProof":"Les infections associées aux soins.pptx — slides 5–7"},{"courseId":"C6","bmAnswer":"D (1-4)","id":"ERR_9","courseAnswer":"C (1-2-3)","bmRef":"Ch. 10 Q22 (ND)","lessonId":"L6.2","topic":"Colonisation d’un cathéter","reason":"La colonisation associe culture positive + ABSENCE de signes locaux et généraux. L’érythème (item 4) signe une infection locale, pas une colonisation.","courseProof":"IAS.pptx — cathéters, slide 18"},{"courseId":"C2","bmAnswer":"B vs C","id":"ERR_10","courseAnswer":"Nuance C2/C3","bmRef":"Ch. 12 Q1 vs Q6 (2024)","lessonId":"L2.1","topic":"MT dans le monde vs contagiosité","reason":"Contradiction interne BM : les MT prédominent dans les PED (dans le monde, MNT = 74 % des décès). Toutes les contagieuses sont transmissibles mais l’inverse est faux.","courseProof":"Épidémiologie des MT — Dr Beichi, p. 2"},{"courseId":"C2","bmAnswer":"ABC / ABCD / C","id":"ERR_11","courseAnswer":"ABCD / CE","bmRef":"Ch. 12 Q9 vs Ch. 38 Q1/Q11","lessonId":"L2.2","topic":"Surveillance des MDO","reason":"Trois clés divergentes dans la BM pour la même notion : MDO = surveillance passive, exhaustive, obligatoire (Décret 22-250), médecins et biologistes (y compris secteur libéral).","courseProof":"Épidémiologie des MT — p. 7–8 + 7.EMT.pdf p. 6"},{"courseId":"C14","bmAnswer":"B","id":"ERR_12","courseAnswer":"A","bmRef":"Ch. 14 Q11 (2024)","lessonId":"L14.1","topic":"Définition de la Cible d’une étude","reason":"La cible est la variable que l’on se propose de mesurer (A). La période d’observation (B) correspond à la manœuvre/temps (clé copiée par erreur de Q12).","courseProof":"Les études épidémiologiques — Kadir MY, slide 17"},{"courseId":"C14","bmAnswer":"A","id":"ERR_13","courseAnswer":"B","bmRef":"Ch. 14 Q27 (2024)","lessonId":"L14.4","topic":"Biais de classement vs biais de sélection","reason":"L’item A (constitution des groupes) définit un biais de SÉLECTION, pas de classement ! Le biais de classement s’évite lors de la conception du protocole (B).","courseProof":"Les études épidémiologiques — Kadir MY, slides 43–44"},{"courseId":"C14","bmAnswer":"D","id":"ERR_14","courseAnswer":"B","bmRef":"Ch. 14 Q28 (2024)","lessonId":"L14.2","topic":"Finalité d’une étude descriptive","reason":"Une étude descriptive décrit selon temps/lieu/personnes (B) et génère des HYPOTHÈSES (jamais des « mesures étiologiques » D).","courseProof":"Les études épidémiologiques — Kadir MY, slides 18–19"},{"courseId":"C14","bmAnswer":"ABCD","id":"ERR_15","courseAnswer":"ABC","bmRef":"Ch. 14 Q31 (2022)","lessonId":"L14.3","topic":"Risque Relatif (RR) vs FER","reason":"L’item D (contribution d’un FDR) correspond à la Fraction Étiologique du Risque (FER) / Risque Attribuable, pas au RR (confirmé par Ch. 14 Q16 [2024] = C).","courseProof":"Les études épidémiologiques — Kadir MY, slide 34"},{"courseId":"C14","bmAnswer":"ACD","id":"ERR_16","courseAnswer":"BCD","bmRef":"Ch. 14 Q40 (2022)","lessonId":"L14.2","topic":"Groupe de comparaison en étude descriptive","reason":"Une étude descriptive ne comporte PAS de groupe de comparaison (A faux !). Confirmé par son doublon exact Ch. 14 Q41 = BCD.","courseProof":"Les études épidémiologiques — Kadir MY, slide 18"},{"courseId":"C4","bmAnswer":"B","id":"ERR_17","courseAnswer":"BCD","bmRef":"Ch. 14 Q49 (ND)","lessonId":"L4.2","topic":"Apports de la courbe épidémique","reason":"La courbe épidémique renseigne sur l’incubation (B), le type de transmission (C) ET la nature de la source (D), mais jamais avec certitude sur l’agent causal (A).","courseProof":"Investigation d’une épidémie — Dr Beichi, p. 6"},{"courseId":"C14","bmAnswer":"AD","id":"ERR_18","courseAnswer":"D","bmRef":"Ch. 14 Q50 (ND)","lessonId":"L14.3","topic":"Fraction Étiologique du Risque (FER)","reason":"A (mesure d’association) définit RR/OR ; la FER est une mesure d’impact/contribution (D).","courseProof":"Les études épidémiologiques — Kadir MY, slide 34"},{"courseId":"C15","bmAnswer":"C (3,5‰) avec « 144 »","id":"ERR_19","courseAnswer":"44 / 12 900 = 3,41‰","bmRef":"Ch. 17 Q20 (2019)","lessonId":"L15.3","topic":"Coquille énoncé Létalité paludisme (Camp)","reason":"La BM imprime par erreur « 144 décès » au lieu de « 44 décès » (cours Pr Tobbi p. 10). La clé C (3,5‰) n’est juste qu’avec 44/12 900 !","courseProof":"Indicateurs de santé — Pr Tobbi, p. 10"},{"courseId":"C15","bmAnswer":"C (25‰)","id":"ERR_20","courseAnswer":"2,44 ‰","bmRef":"Ch. 17 Q22 (2019)","lessonId":"L15.3","topic":"Erreur facteur ×10 sur TMS paludisme (Camp)","reason":"Erreur de facteur ×10 dans la BM : 44 / 18 000 = 2,44 ‰ (virgule sautée sur 2,5‰ → imprimé 25‰ !).","courseProof":"Indicateurs de santé — Pr Tobbi, p. 10"},{"courseId":"C25","bmAnswer":"B (omission Objectif)","id":"ERR_21","courseAnswer":"Objectif + Méthodes + début Résultats","bmRef":"Ch. 21 Q1 (2024)","lessonId":"L25.2","topic":"Définition de la lecture diagonale en LCA","reason":"La clé B (« Matériel et méthodes et résultats ») omet le dernier paragraphe de l’Introduction (Objectif), pourtant exigé dans les 2 cours (Dr Chiboub p. 4 \u0026 Dr Benaldjia slide 58).","courseProof":"Principe et technique LCA p. 4 \u0026 LCA conférence slide 58"},{"courseId":"C13","bmAnswer":"B","id":"ERR_22","courseAnswer":"D","bmRef":"Ch. 29 Q43 == Ch. 41 Q35 (2021)","lessonId":"L13.3","topic":"Caractéristique principale d’un système de santé","reason":"B (optique d’hospitalisation) définit le système de SOINS. Le système de SANTÉ est un ensemble de mesures réduisant la fréquence des pathologies (D, confirmé par Ch. 29 Q6 [2024] = D !).","courseProof":"Système de santé Monde \u0026 Algérie — pp. 9–10"},{"courseId":"C17","bmAnswer":"B","id":"ERR_23","courseAnswer":"ABC","bmRef":"Ch. 32 Q6 (2021)","lessonId":"L17.2","topic":"Identification des besoins en programmation","reason":"L’identification des besoins combine surveillance (A), enquêtes épidémiologiques (B) ET perception de la communauté / enquêtes socio-psychologiques (C).","courseProof":"Programmation sanitaire — Dr Aouidane, slides 10–11"},{"courseId":"C16","bmAnswer":"A (naissance)","id":"ERR_24","courseAnswer":"D (11 mois)","bmRef":"Ch. 33 Q11 (2024)","lessonId":"L16.1","topic":"Âge d’administration du ROR","reason":"Le ROR s’administre à 11 mois (1re dose) et 18 mois (2e dose), jamais à la naissance (BCG + HBV). Confirmé par Ch. 33 Q12 = D !","courseProof":"PEV 2023 p. 41 \u0026 PEV 2026-207 p. 44"},{"courseId":"C11","bmAnswer":"A","id":"ERR_25","courseAnswer":"C","bmRef":"Ch. 37 Q14 (2019)","lessonId":"L11.3","topic":"Définition de l’étendue","reason":"L’étendue = Max − Min de la série (C). L’item A (borne sup − borne inf d’une classe) définit l’amplitude d’une classe.","courseProof":"Statistique descriptive 2026 — Pr Benaldjia, slide 64"},{"courseId":"C11","bmAnswer":"C / BE","id":"ERR_26","courseAnswer":"BC / BDE","bmRef":"Ch. 37 Q11 \u0026 Q24 (2022/ND)","lessonId":"L11.3","topic":"Propriétés du Coefficient de variation (CV)","reason":"Le CV s’exprime en % (B), vaut s/m × 100 (C) et exprime le degré de dispersion en fonction de la moyenne (D).","courseProof":"Statistique descriptive 2026 — Pr Benaldjia, slide 68"}]$m25j$::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
INSERT INTO public.site_meta (key, value) VALUES ('outOfCourseBM', $m25j$[{"chapters":"Ch. 25 \u0026 Ch. 28 — Outils d’analyse économique / Consommation médicale (PIB, IDH, G. Rosch)","note":"Ch. 28 est un doublon intégral (23/23) de Ch. 25. Hors supports d’Épidémiologie fournis.","count":46},{"chapters":"Ch. 4 — Besoin et demande de santé (3 cercles, élasticité, offre/demande)","note":"Économie de la santé (recoupe partiellement la rareté des ressources en C9).","count":24},{"chapters":"Ch. 27 — Médicament générique, princeps \u0026 pharmacovigilance","note":"Cours d’Économie du médicament non présent dans le dossier des 51 fichiers.","count":19},{"chapters":"Ch. 18 — Indicateurs économiques de la santé (Coût-efficacité, CMT, DCS)","note":"Économie de la santé hors polycopiés fournis.","count":15},{"chapters":"Ch. 3 (Q2, Q3, Q4) \u0026 Ch. 14 (Q13 doublon Ch. 3 Q4, Q14–Q15)","note":"Évaluation médico-économique, épidémiologie clinique, stat. inférentielle et histoire naturelle hors polycopié.","count":6},{"chapters":"Ch. 39 — Système d’information médicalisé (SIS / DEP)","note":"Chapitre court hors supports fournis.","count":2},{"chapters":"Ch. 40 (Q2, Q3) — Système de protection sociale","note":"Q1 déjà rattachée à C9 (Financement).","count":2},{"chapters":"Ch. 30 — Outils d’analyse économique en santé (chapitre vide)","note":"Intercalaire seul dans le livret BM (0 question).","count":0}]$m25j$::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
INSERT INTO public.site_meta (key, value) VALUES ('masterExamAnalysis', $m25j${"methodology":[{"rule":"0 Q = 0 · 1 Q = 12 · 2 Q = 22 · 3 Q = 30 · 4 Q = 36 · 5 Q = 40 · ≥ 6 Q = 45","criterion":"1. Fréquence réelle BM","maxPts":45,"nature":"Donnée factuelle"},{"rule":"Formulations (0–15 pts) + Récence (+5 si 2024, +10 si 2025 ou 2024–2025)","criterion":"2. Formulations distinctes + Récence 2024–2025","maxPts":25,"nature":"Donnée factuelle"},{"rule":"15 = pilier central · 10 = section majeure · 5 = complément","criterion":"3. Importance structurelle dans le cours","maxPts":15,"nature":"Estimation qualitative"},{"rule":"+5 définitions/seuils · +5 formules/calculs · +5 confusions classiques ou erreur BM","criterion":"4. Calculs, définitions, pièges \u0026 erreurs BM","maxPts":15,"nature":"Estimation qualitative"}],"courseFrequencies":[{"courseId":"C13","priorityScore":95,"recent2024_2025":6,"uniqueConcepts":23,"title":"Organisation des systèmes de santé (Monde \u0026 Algérie)","note":"N°1 volume brut (Ch. 29 + Ch. 41 doublon 1-à-1 ; 6 Q p. 184 récupérées ; 48 directs + 39 hors-poly).","code":"C13","rawCount":87,"priority":"very_high","uniqueQuestions":46},{"courseId":"C14","priorityScore":100,"recent2024_2025":22,"uniqueConcepts":14,"title":"Les études épidémiologiques (+ TD)","note":"N°1 en diversité conceptuelle \u0026 22 Q récentes 2024–2025 + 7 erreurs BM graves.","code":"C14","rawCount":45,"priority":"very_high","uniqueQuestions":37},{"courseId":"C15","priorityScore":95,"recent2024_2025":2,"uniqueConcepts":10,"title":"Démographie et indicateurs de santé (Pr Tobbi)","note":"Quatuor calculs mortalité (15 Q) + outils math (6 Q) + incidence (6 Q) ; 2 erreurs ×10/coquille.","code":"C15","rawCount":31,"priority":"very_high","uniqueQuestions":23},{"courseId":"C2","priorityScore":90,"recent2024_2025":7,"uniqueConcepts":10,"title":"Épidémiologie des MT \u0026 Surveillance","note":"MDO Décret 22-250 (+ 7.EMT.pdf 6 nouvelles MDO 2022) + Ch. 38 attributs surveillance.","code":"C2","rawCount":30,"priority":"very_high","uniqueQuestions":26},{"courseId":"C6","priorityScore":95,"recent2024_2025":8,"uniqueConcepts":8,"title":"IAS, Précautions Standard, Hygiène \u0026 EPI (5 PPTX)","note":"4 nouveaux PPTX couvrent 8 QCM d’hygiène + règle SmartArt gants ; 4 erreurs BM corrigées.","code":"C6","rawCount":28,"priority":"very_high","uniqueQuestions":25},{"courseId":"C11","priorityScore":100,"recent2024_2025":7,"uniqueConcepts":7,"title":"Statistique descriptive (+ TD)","note":"Graphiques (10 Q) + Dispersion Variance/CV/Étendue (10 Q) + 3 erreurs BM.","code":"C11","rawCount":28,"priority":"very_high","uniqueQuestions":24},{"courseId":"C16","priorityScore":95,"recent2024_2025":16,"uniqueConcepts":6,"title":"PEV 2023 \u0026 Mise à jour PEV 2026–2027 (HPV)","note":"100 % des Q en 2024–2025 + Arrêté HPV 28/04/2026, nVPO2, MPVI Fiche Blanche CNPM.","code":"C16","rawCount":16,"priority":"very_high","uniqueQuestions":12},{"courseId":"C1","priorityScore":95,"recent2024_2025":6,"uniqueConcepts":5,"title":"Introduction à la santé publique","note":"Prévention (10 occ. cumulées C1+C3) + 3 approches + 2 erreurs BM majeures.","code":"C1","rawCount":15,"priority":"very_high","uniqueQuestions":14},{"courseId":"C17","priorityScore":75,"recent2024_2025":1,"uniqueConcepts":6,"title":"Programmation sanitaire","note":"Besoins (erreur BM Q6), Objectif vs Activité, Pertinence, Planification ≠ Programmation.","code":"C17","rawCount":12,"priority":"high","uniqueQuestions":9},{"courseId":"C4","priorityScore":86,"recent2024_2025":5,"uniqueConcepts":6,"title":"Investigation d’une épidémie","note":"5 Q neuves en 2025 sur un cours de 8 pages ; erreur BM Ch. 14 Q49.","code":"C4","rawCount":11,"priority":"high","uniqueQuestions":10},{"courseId":"C7","priorityScore":80,"recent2024_2025":8,"uniqueConcepts":4,"title":"Santé scolaire (2 PDF)","note":"8 Q d’un coup en 2025 (Ch. 26 Q1–Q7 + Ch. 13 Q3 Trachome) ; piège 2AM vs 1AM.","code":"C7","rawCount":8,"priority":"high","uniqueQuestions":8},{"courseId":"C23","priorityScore":75,"recent2024_2025":8,"uniqueConcepts":5,"title":"Communication \u0026 Rédaction scientifique","note":"OUAC, Conatif, 3 obj. ACC, entonnoir IMRED ; 2 erreurs BM franches Ch. 7.","code":"C23","rawCount":8,"priority":"high","uniqueQuestions":5},{"courseId":"C9","priorityScore":65,"recent2024_2025":0,"uniqueConcepts":3,"title":"Financement du système de santé","note":"Sources Algérie (CNAS/CASNOS) + Équité / Efficacité / Pérennité.","code":"C9","rawCount":6,"priority":"medium","uniqueQuestions":5},{"courseId":"C5","priorityScore":65,"recent2024_2025":5,"uniqueConcepts":3,"title":"Conduite à tenir \u0026 Prévention des TIAC","note":"5 Q en 2024 + Instruction Ministérielle N°19 juillet 2026.","code":"C5","rawCount":5,"priority":"high","uniqueQuestions":4},{"courseId":"C3","priorityScore":60,"recent2024_2025":1,"uniqueConcepts":3,"title":"Maladies non transmissibles (MNT)","note":"Couplé à C1 (prévention) + transition épidémiologique (2025).","code":"C3","rawCount":5,"priority":"medium","uniqueQuestions":5},{"courseId":"C18","priorityScore":81,"recent2024_2025":5,"uniqueConcepts":4,"title":"CAT Méningite à méningocoque (MCS)","note":"100 % en 2024–2025 ; contacts 10 j, sérogroupe A 90 %, erreur BM Ch. 5 Q3.","code":"C18","rawCount":5,"priority":"high","uniqueQuestions":4},{"courseId":"C22","priorityScore":76,"recent2024_2025":4,"uniqueConcepts":3,"title":"Recherche bibliographique (Init. \u0026 IA nov. 2026)","note":"Vancouver 5 zones (2024+2025), preprints + nouvelle partie IA \u0026 Prompting nov. 2026.","code":"C22","rawCount":4,"priority":"high","uniqueQuestions":3},{"courseId":"C24","priorityScore":81,"recent2024_2025":4,"uniqueConcepts":4,"title":"Outils de validité des mesures (Se, Sp, VPP, VPN)","note":"4 pages très rentables, 100 % 2024–2025 + calcul BU/ECBU.","code":"C24","rawCount":4,"priority":"high","uniqueQuestions":4},{"courseId":"C25","priorityScore":76,"recent2024_2025":4,"uniqueConcepts":4,"title":"Lecture Critique d’Articles médicaux (LCA — 5 sous-cours)","note":"VIP, NP1 HAS, Lecture diagonale + 3 sous-cours neufs (diagnostique, STROBE, quasi-exp.).","code":"C25","rawCount":4,"priority":"high","uniqueQuestions":4},{"courseId":"C19","priorityScore":75,"recent2024_2025":3,"uniqueConcepts":1,"title":"Contrôle et suivi antituberculeux (SCTMR)","note":"Dépistage actif (RX+IDR) \u0026 passif en 2024+2025 + INH 6 mois \u003c 5 ans, M2/M4/M6.","code":"C19","rawCount":3,"priority":"medium","uniqueQuestions":2},{"courseId":"C10","priorityScore":57,"recent2024_2025":2,"uniqueConcepts":1,"title":"Élaboration du questionnaire d’une étude","note":"2 pages seulement, tombé 2024 \u0026 2025 (phase de planification).","code":"C10","rawCount":2,"priority":"medium","uniqueQuestions":1},{"courseId":"C12","priorityScore":67,"recent2024_2025":2,"uniqueConcepts":1,"title":"Test d’hypothèse : Comparaison de 2 % (χ²)","note":"1 exercice χ² en 2024 et 1 en 2025 (Cij ≥ 5, ddl=1, seuil 3,841).","code":"C12","rawCount":2,"priority":"medium","uniqueQuestions":2},{"courseId":"C20","priorityScore":62,"recent2024_2025":2,"uniqueConcepts":1,"title":"Règlement Sanitaire International (RSI)","note":"4 pages, tombé 2024 \u0026 2025 (196 pays, 1951/2005/2007, USPPI, PFN).","code":"C20","rawCount":2,"priority":"medium","uniqueQuestions":2},{"courseId":"C21","priorityScore":47,"recent2024_2025":1,"uniqueConcepts":1,"title":"Introduction à la méthodologie de recherche","note":"Inductif vs déductif (2025) + EDIE / PICO.","code":"C21","rawCount":1,"priority":"medium","uniqueQuestions":1},{"courseId":"C8","vigilance2026":true,"priorityScore":45,"recent2024_2025":0,"uniqueConcepts":0,"title":"Certification Cause Médicale de Décès (CMD)","note":"0 Q BM car cours 2024–2025 sur Décret 22-178 : HAUTE VIGILANCE 2026 !","code":"C8","rawCount":0,"priority":"medium","uniqueQuestions":0}],"version":"Master 01 — Audit 25 Cours (2026)","topRepetitions":[{"courseId":"C15","rank":1,"refs":"2019 (Ch.17 Q19–22), 2021 (Q15–18), 2022