INSERT INTO public.site_meta (key, value) VALUES ('masterFinalStrategy', $m25j${"top20Themes":[{"courseId":"C11","rank":1,"theme":"Représentations graphiques selon type de variable (Histogramme, Barres, Bâtons, Circulaire 1%=3,6°, Polygone, Boxplot)","score":100,"courseLabel":"C11 — Stat. descriptive","proof":"10 Q (2019–2025)"},{"courseId":"C1","rank":2,"theme":"Les 4 niveaux de prévention (Primaire ↓I, Secondaire ↓P/dépistage, Tertiaire, Quaternaire)","score":100,"courseLabel":"C1 \u0026 C3 — Intro SP / MNT","proof":"10 Q (2021–2025)"},{"courseId":"C14","rank":3,"theme":"Notion de Cible d’une étude (maladie en cohorte, exposition en cas-témoins ≠ manœuvre)","score":100,"courseLabel":"C14 — Études épid.","proof":"6 Q (2021–2025)"},{"courseId":"C15","rank":4,"theme":"Quatuor de calculs de mortalité sur vignette (TBM, Létalité, RPM, TMS — dénominateurs !)","score":95,"courseLabel":"C15 — Indicateurs (Tobbi)","proof":"15 Q (2019–2024)"},{"courseId":"C13","rank":5,"theme":"Modèles mondiaux : Beveridge (1948, impôt, sans affiliation), Bismarck (1883, cotisations), Mixte USA (15 % non couverts)","score":95,"courseLabel":"C13 — Systèmes de santé","proof":"20 Q (11 slots ; 2021–2024)"},{"courseId":"C13","rank":6,"theme":"Système de santé vs Système de soins (5 critères + erreur BM Ch. 29 Q43)","score":95,"courseLabel":"C13 — Systèmes de santé","proof":"10 Q (6 slots ; 2021–2024)"},{"courseId":"C16","rank":7,"theme":"Calendrier vaccinal algérien (BCG+HBV naissance, ROR 11 \u0026 18 mois + Arrêté HPV 28/04/2026 à 11–13 ans)","score":95,"courseLabel":"C16 — PEV 2023 \u0026 2026","proof":"8 Q (2024)"},{"courseId":"C6","rank":8,"theme":"Localisations des IN \u0026 germes (IUN 1er site E. coli ; Pneumonie 1re cause décès BGN ; Cathéter Staph ; ISO 30 j / 1 an prothèse)","score":95,"courseLabel":"C6 — IAS \u0026 Hygiène","proof":"8 Q (2021–2025)"},{"courseId":"C11","rank":9,"theme":"Paramètres de dispersion : Variance, Écart-type, CV (s/m × 100 en %), Étendue (max − min)","score"